'use client';

import { useCallback, useEffect, useMemo, useState } from 'react';
import { Activity, ArrowDownRight, ArrowUpRight, Bell, Blocks, Box, ChevronDown, ChevronLeft, ChevronRight, CircleHelp, Cloud, Code2, Command, CreditCard, Database, Download, FileText, FolderPlus, Globe2, HardDrive, LayoutDashboard, LifeBuoy, LockKeyhole, LogOut, Mail, Menu, MoreHorizontal, Pencil, Plus, RefreshCw, Search, Server, Settings2, ShieldCheck, Sparkles, Trash2, Upload, Users, X, Zap } from 'lucide-react';
import { Bar, BarChart, CartesianGrid, Cell, ResponsiveContainer, Tooltip, XAxis, YAxis } from 'recharts';
import Editor from '@monaco-editor/react';

type User = { id: string; email: string; username?: string | null; name: string; role: string; mustChangePassword: boolean };
type Customer = { id: string; name: string; email: string; mustChangePassword: boolean; disabledAt: string | null; websiteLimit: number; websiteCount: number; createdAt: string };
type NodeInfo = { id: string; name: string; hostname: string; region?: string | null; status: string; agentVersion?: string | null; online: boolean; cpuPercent?: number | null; memoryUsed?: string | null; memoryTotal?: string | null; diskUsed?: string | null; diskTotal?: string | null };
type ActivityItem = { id: string; actor: string; action: string; resource: string; resourceId?: string | null; createdAt: string };
type Overview = { user: { name: string; role: string }; metrics: { nodes: number; liveNodes: number; websites: number; websiteLimit: number | null; queuedJobs: number }; nodes: NodeInfo[]; activity: ActivityItem[]; capabilities: { provisioning: string; reason: string } };
type Website = { id: string; primaryDomain: string; status: string; runtime: string; tlsStatus: string; node?: { name: string } | null; createdAt: string };
type ProvisioningJob = { id: string; type: string; status: 'QUEUED' | 'RUNNING' | 'SUCCEEDED' | 'FAILED' | 'CANCELLED'; attempts: number; createdAt: string; updatedAt: string; website: { primaryDomain: string } | null };
type Health = { status: string; database: string; schema?: string };
type InstallStatus = { status: string; completedAt: string | null; lastError: string | null; steps: { id: string; label: string; status: string }[]; localNodes: { id: string; hostname: string; operatingSystem: string | null; cpuCores: number | null; ipAddresses: string[]; systemInfo: { architecture?: string; virtualization?: string; services?: string[] } | null; status: string; agentVersion: string | null; lastHeartbeat: string | null; bootstrapIssuedAt: string | null; agentUrl: string | null }[] };

const groups = [
  { label: 'Workspace', items: [{ name: 'Overview', icon: LayoutDashboard }, { name: 'Websites', icon: Globe2, countKey: 'websites' }, { name: 'Provisioning jobs', icon: Zap, countKey: 'queuedJobs' }, { name: 'Domains & DNS', icon: Cloud }, { name: 'Files', icon: HardDrive }, { name: 'Databases', icon: Database }, { name: 'Email', icon: Mail }] },
  { label: 'Manage', items: [{ name: 'Servers', icon: Server, countKey: 'nodes' }, { name: 'Customers', icon: Users }, { name: 'Security', icon: ShieldCheck }, { name: 'Billing', icon: CreditCard }, { name: 'Activity log', icon: Activity }] },
];

async function api<T>(path: string, init?: RequestInit): Promise<T> {
  const response = await fetch(path, { ...init, credentials: 'include', headers: { 'Content-Type': 'application/json', ...init?.headers } });
  const body = await response.json().catch(() => ({}));
  if (!response.ok) throw new Error(body.error ?? `Request failed (${response.status})`);
  return body as T;
}
const formatDate = (date: string) => new Intl.DateTimeFormat(undefined, { month: 'short', day: 'numeric', hour: 'numeric', minute: '2-digit' }).format(new Date(date));
const shortBytes = (bytes?: string | null) => { if (!bytes) return '—'; const value = Number(bytes); if (!Number.isFinite(value)) return '—'; return `${(value / 1024 ** 3).toFixed(1)} GB`; };

export default function Home() {
  const [user, setUser] = useState<User | null>(null);
  const [overview, setOverview] = useState<Overview | null>(null);
  const [websites, setWebsites] = useState<Website[]>([]);
  const [jobs, setJobs] = useState<ProvisioningJob[]>([]);
  const [health, setHealth] = useState<Health | null>(null);
  const [setupEnabled, setSetupEnabled] = useState(false);
  const [loading, setLoading] = useState(true);
  const [active, setActive] = useState('Overview');
  const [sidebarOpen, setSidebarOpen] = useState(false);
  const [error, setError] = useState('');

  const refresh = useCallback(async () => {
    try {
      const [result, listed, recentJobs] = await Promise.all([
        api<Overview>('/api/overview'),
        api<{ websites: Website[] }>('/api/websites'),
        api<{ jobs: ProvisioningJob[] }>('/api/jobs?limit=30'),
      ]);
      setOverview(result);
      setWebsites(listed.websites);
      setJobs(recentJobs.jobs);
    } catch (e) { if (e instanceof Error && !e.message.includes('Authentication')) setError(e.message); }
  }, []);

  useEffect(() => {
    Promise.all([api<Health>('/api/health').then(setHealth).catch(() => setHealth({ status: 'offline', database: 'unavailable' })), api<{ setupEnabled: boolean }>('/api/auth/setup-status').then((result) => setSetupEnabled(result.setupEnabled)).catch(() => undefined), api<{ user: User }>('/api/auth/me').then((result) => setUser(result.user)).catch(() => undefined)]).finally(() => setLoading(false));
  }, []);
  useEffect(() => {
    if (!user) return;
    void refresh();
    const timer = window.setInterval(() => void refresh(), 30_000);
    return () => window.clearInterval(timer);
  }, [user, refresh]);
  useEffect(() => {
    const navigate = (event: Event) => setActive((event as CustomEvent<string>).detail);
    window.addEventListener('nova-navigate', navigate);
    return () => window.removeEventListener('nova-navigate', navigate);
  }, []);

  const logout = async () => { await api('/api/auth/logout', { method: 'POST' }).catch(() => undefined); setUser(null); setOverview(null); };
  const activeGroup = useMemo(() => groups.flatMap((g) => g.items).find((item) => item.name === active), [active]);

  if (loading) return <div className="loading-screen"><div className="brand-mark"><Sparkles size={21} /></div><span>Preparing your control plane</span></div>;
  if (!user) return <AuthScreen setupEnabled={setupEnabled} health={health} onSuccess={(next) => setUser(next)} />;
  if (user.mustChangePassword) return <PasswordChangeScreen user={user} onSuccess={(next) => setUser(next)} onLogout={logout} />;

  return <div className="shell">
    <aside className={`sidebar ${sidebarOpen ? 'sidebar-open' : ''}`}>
      <div className="brand"><div className="brand-mark"><Sparkles size={19} strokeWidth={2.5} /></div><span>nova<span className="brand-light">hosting</span></span><button className="close-sidebar" onClick={() => setSidebarOpen(false)}><X size={17} /></button></div>
      <button className="workspace-switch"><div className="workspace-icon">N</div><div className="workspace-text"><strong>Nova Console</strong><span>{user.role === 'ADMIN' ? 'Control plane' : 'Customer account'}</span></div><ChevronDown size={15} /></button>
      <button className="search-trigger" disabled title="Global search is not enabled yet"><Search size={15} /><span>Search anything</span><kbd>⌘ K</kbd></button>
      <nav className="nav-list">{groups.map((group) => <div className="nav-group" key={group.label}><div className="nav-label">{group.label}</div>{group.items.filter(({ name }) => user.role === 'ADMIN' || !['Servers', 'Customers', 'Security', 'Activity log'].includes(name)).map(({ name, icon: Icon, countKey }) => <button key={name} className={`nav-item ${active === name ? 'selected' : ''}`} onClick={() => { setActive(name); setSidebarOpen(false); }}><Icon size={17} strokeWidth={1.8} /><span>{name}</span>{countKey && overview?.metrics[countKey as keyof Overview['metrics']] !== undefined && <span className="nav-count">{overview.metrics[countKey as keyof Overview['metrics']]}</span>}</button>)}</div>)}</nav>
      <div className="sidebar-bottom"><div className="help-card"><div className="help-icon"><LifeBuoy size={16} /></div><div><strong>Need a hand?</strong><span>Explore the quickstart</span></div><ChevronRight size={15} /></div><button className="nav-item" onClick={() => setActive('Settings')}><Settings2 size={17} /><span>Settings</span></button><div className="profile"><div className="avatar">{(user.name || user.email).slice(0, 1).toUpperCase()}</div><div className="profile-copy"><strong>{user.name || user.email.split('@')[0]}</strong><span>{user.email}</span></div><button className="icon-button" aria-label="Sign out" onClick={logout}><LogOut size={16} /></button></div></div>
    </aside>
    {sidebarOpen && <button className="mobile-scrim" aria-label="Close menu" onClick={() => setSidebarOpen(false)} />}
    <main className="main-area"><header className="topbar"><div className="topbar-left"><button className="mobile-menu icon-button" onClick={() => setSidebarOpen(true)} aria-label="Open menu"><Menu size={20} /></button><span className="breadcrumb-muted">Console</span><ChevronRight size={14} className="crumb-chevron" /><span className="breadcrumb-current">{active}</span></div><div className="topbar-actions"><div className="region-pill"><span className={`green-dot ${health?.database === 'connected' ? '' : 'status-warn'}`} />{health?.database === 'connected' ? (overview?.metrics.liveNodes ? 'Nodes reporting' : 'Setup needed') : 'Setup needed'}</div><button className="icon-button notification" aria-label="Notifications" disabled title="Notifications are not connected yet"><Bell size={17} /></button><div className="top-divider" /><button className="avatar top-avatar">{(user.name || user.email).slice(0, 1).toUpperCase()}</button></div></header>
      <div className="page-content">{error && <div className="error-banner"><ShieldCheck size={16} /><span>{error}</span><button onClick={() => setError('')}><X size={15} /></button></div>}
        {active === 'Overview' ? <OverviewPage overview={overview} health={health} /> : active === 'Websites' ? <WebsitesPage websites={websites} canProvision={Boolean(overview?.metrics.liveNodes)} onRefresh={refresh} /> : active === 'Provisioning jobs' ? <JobsPage jobs={jobs} onRefresh={refresh} /> : active === 'Customers' ? <CustomersPage /> : active === 'Activity log' ? <ActivityPage /> : active === 'Settings' ? <AccountSettingsPage onUserChange={setUser} /> : active === 'Files' ? <FilesPage websites={websites} /> : active === 'Servers' ? <ServersPage overview={overview} onRefresh={refresh} /> : <UnavailablePage title={active} icon={activeGroup?.icon ?? Blocks} />}
      </div>
      <footer className="footer"><span>Nova Hosting <span className="footer-version">CONTROL PLANE · 0.1.0</span></span><span><i className={`footer-dot ${health?.status === 'ok' && health.database === 'connected' ? 'good' : 'warn'}`} />API {health?.status === 'ok' ? 'reachable' : 'unavailable'} <span className="footer-sep">·</span> Database {health?.database ?? 'checking'}</span></footer>
    </main>
  </div>;
}

function InstallationPanel() {
  const [state, setState] = useState<InstallStatus | null>(null);
  const [bootstrap, setBootstrap] = useState<{ nodeId: string; hostname: string; sharedSecret: string; agentUrl: string | null; controlUrl: string | null } | null>(null);
  const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [agentUrl, setAgentUrl] = useState('');
  const load = async (syncForm = true) => { try { const next = await api<InstallStatus>('/api/install/status'); setState(next); if (syncForm) setAgentUrl(next.localNodes[0]?.agentUrl ?? ''); setError(''); } catch (e) { setError(e instanceof Error ? e.message : 'Installation status is unavailable.'); } };
  const saveAgentUrl = async (event: React.FormEvent) => { event.preventDefault(); setBusy(true); setError(''); try { await api('/api/install/local-agent-url', { method: 'PUT', body: JSON.stringify({ agentUrl }) }); await load(); } catch (e) { setError(e instanceof Error ? e.message : 'Agent URL could not be saved.'); } finally { setBusy(false); } };
  const registerLocalNode = async () => { setBusy(true); setError(''); try { await api('/api/install/local-node', { method: 'POST', body: '{}' }); await load(); } catch (e) { setError(e instanceof Error ? e.message : 'Local Node could not be registered.'); } finally { setBusy(false); } };
  useEffect(() => { void load(); const timer = window.setInterval(() => void load(false), 30_000); return () => window.clearInterval(timer); }, []);
  const issue = async (rotate: boolean) => { if (rotate && !window.confirm('Rotate the Local Node key? The existing agent will lose access until its root-owned environment file is updated.')) return; setBusy(true); setError(''); try { const result = await api<{ bootstrap: { nodeId: string; hostname: string; sharedSecret: string; agentUrl: string | null }; controlUrl: string | null }>('/api/install/local-agent-bootstrap', { method: 'POST', body: JSON.stringify(rotate ? { rotate: true } : {}) }); setBootstrap({ ...result.bootstrap, controlUrl: result.controlUrl }); await load(); } catch (e) { setError(e instanceof Error ? e.message : 'Bootstrap credentials could not be issued.'); } finally { setBusy(false); } };
  const copy = async () => { if (!bootstrap) return; await navigator.clipboard.writeText(`NOVA_NODE_ID=${bootstrap.nodeId}\nNOVA_SHARED_SECRET=${bootstrap.sharedSecret}\nNOVA_CONTROL_URL=${bootstrap.controlUrl ?? 'SET_HTTPS_PANEL_ORIGIN'}\nNOVA_TLS_CERT=/etc/letsencrypt/live/agent.example.com/fullchain.pem\nNOVA_TLS_KEY=/etc/letsencrypt/live/agent.example.com/privkey.pem\nNOVA_ACME_EMAIL=ops@example.com`); };
  return <section className="panel install-panel"><div className="panel-heading"><div><h2>First-run installation</h2><p>Live database, administrator, Local Node and signed-agent state</p></div><button className="subtle-link" onClick={() => void load()}><RefreshCw size={14} />Refresh</button></div>{error && <div className="auth-error"><ShieldCheck size={15} />{error}</div>}<div className="install-steps">{(state?.steps ?? []).map((step) => <div className="feature-status" key={step.id}><span><i />{step.label}</span><b>{step.status === 'complete' ? 'Complete' : step.status === 'waiting' ? 'Waiting' : 'Action required'}</b></div>)}</div>{state?.lastError && <p className="auth-system-note">{state.lastError}</p>}{state && !state.localNodes.length && <button className="primary-button" disabled={busy} onClick={() => void registerLocalNode()}>{busy ? 'Registering…' : 'Register this machine as the Local Node'}</button>}{state?.localNodes.map((node) => <div key={node.id}><p className="install-node-detail"><b>Local Node:</b> {node.hostname} · {node.operatingSystem ?? 'OS awaits agent inventory'} · {node.cpuCores ? `${node.cpuCores} CPU cores` : 'CPU awaits agent inventory'} · {node.ipAddresses.join(', ') || 'IP awaits agent inventory'}{node.systemInfo?.architecture ? ` · ${node.systemInfo.architecture}` : ''}{node.systemInfo?.virtualization ? ` · Virtualization: ${node.systemInfo.virtualization}` : ''}{node.systemInfo?.services?.length ? ` · Services: ${node.systemInfo.services.join(', ')}` : ''}</p><form className="install-url-form" onSubmit={(event) => void saveAgentUrl(event)}><label>HTTPS agent endpoint<input type="url" required value={agentUrl} onChange={(event) => setAgentUrl(event.target.value)} placeholder={`https://${node.hostname}:8443`} /></label><button className="primary-button" disabled={busy}>{busy ? 'Saving…' : 'Save agent URL'}</button></form></div>)}{state?.steps.some((step) => step.id === 'agent' && step.status !== 'complete') && <div className="install-agent-action"><p>Provisioning agent setup is deliberately not performed by the web process: it requires reviewed binaries, TLS configuration and root/systemd privileges. Build and install the Go agent on this host using the deployment guide, then wait for its authenticated inventory heartbeat.</p>{bootstrap ? <div className="install-bootstrap"><b>One-time agent bootstrap (copy now; the secret is not shown again)</b><code>NOVA_NODE_ID={bootstrap.nodeId}</code><code>NOVA_SHARED_SECRET={bootstrap.sharedSecret}</code><code>NOVA_CONTROL_URL={bootstrap.controlUrl ?? 'SET_HTTPS_PANEL_ORIGIN'}</code><code>NOVA_TLS_CERT=/etc/letsencrypt/live/agent.example.com/fullchain.pem</code><code>NOVA_TLS_KEY=/etc/letsencrypt/live/agent.example.com/privkey.pem</code><code>NOVA_ACME_EMAIL=ops@example.com</code><button className="primary-button" onClick={() => void copy()}>Copy safe environment values <FileText size={14} /></button><button className="cancel-button" onClick={() => void issue(true)}>Rotate bootstrap key</button></div> : <button className="primary-button" disabled={busy || !state?.localNodes.length} onClick={() => void issue(Boolean(state?.localNodes[0]?.bootstrapIssuedAt))}>{busy ? 'Preparing…' : state?.localNodes[0]?.bootstrapIssuedAt ? 'Rotate Local Node bootstrap' : 'Issue one-time Local Node bootstrap'}</button>}</div>}</section>;
}

function OverviewPage({ overview, health }: { overview: Overview | null; health: Health | null }) {
  const [now] = useState(() => new Date());
  const greeting = now.getHours() < 12 ? 'Good morning' : now.getHours() < 18 ? 'Good afternoon' : 'Good evening';
  const metrics = overview?.metrics;
  const cards = [
    { label: 'Connected nodes', value: metrics?.nodes ?? '—', icon: Server, foot: metrics ? `${metrics.liveNodes} reporting now` : 'Waiting for control plane', tone: 'lime', delta: metrics?.liveNodes ? 'HEALTHY' : 'SETUP' },
    { label: 'Hosted websites', value: metrics?.websites ?? '—', icon: Globe2, foot: metrics?.websiteLimit == null ? 'Across your infrastructure' : `${Math.max(0, metrics.websiteLimit - (metrics.websites ?? 0))} website slots remaining`, tone: 'violet', delta: 'LIVE DATA' },
    { label: 'Provisioning queue', value: metrics?.queuedJobs ?? '—', icon: Zap, foot: 'Background operations', tone: 'blue', delta: 'QUEUE' },
    { label: 'Database', value: health?.database === 'connected' ? 'Online' : 'Offline', icon: Database, foot: 'PostgreSQL control store', tone: health?.database === 'connected' ? 'lime' : 'amber', delta: health?.database === 'connected' ? 'READY' : 'ACTION' },
  ];
  const resourceRows = (overview?.nodes ?? []).filter((node) => node.online && node.cpuPercent !== null && node.cpuPercent !== undefined).map((node) => ({ name: node.name, cpu: Math.round(node.cpuPercent ?? 0) }));
  return <>
    <div className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-line" /> INFRASTRUCTURE OVERVIEW</div><h1>{greeting}, {overview?.user.name ?? 'there'}<span className="wave">✳</span></h1><p className="welcome-sub">Your hosting environment, at a glance.</p></div><button className="date-button"><span className="date-dot" />Live overview <ChevronDown size={14} /></button></div>
    {overview?.user.role === 'ADMIN' && <InstallationPanel />}
    {(!overview || health?.database !== 'connected') && <div className="setup-banner"><div className="setup-symbol"><Settings2 size={20} /></div><div className="setup-copy"><strong>Your control plane needs a database connection</strong><span>Configure PostgreSQL and run migrations to start managing real infrastructure.</span></div><span className="setup-step">01 <ChevronRight size={14} /> 03</span></div>}
    {overview && metrics?.nodes === 0 && <div className="setup-banner node-banner"><div className="setup-symbol"><Server size={20} /></div><div className="setup-copy"><strong>Connect your first hosting node</strong><span>Install the Nova agent on a Linux server. Provisioning stays disabled until a trusted agent is connected.</span></div><button className="text-link" onClick={() => window.dispatchEvent(new CustomEvent('nova-navigate', { detail: 'Servers' }))}>View nodes <ArrowUpRight size={14} /></button></div>}
    <div className="metric-grid">{cards.map((card) => <div className="metric-card" key={card.label}><div className="metric-top"><span>{card.label}</span><div className={`metric-icon ${card.tone}`}><card.icon size={16} /></div></div><div className="metric-value">{card.value}</div><div className="metric-bottom"><span className="metric-note">{card.foot}</span><span className={`metric-badge ${card.tone}`}>{card.delta}</span></div></div>)}</div>
    <div className="content-grid"><section className="panel resource-panel"><div className="panel-heading"><div><h2>Node resources</h2><p>Current utilization reported by your agents</p></div><button className="more-button" aria-label="More options"><MoreHorizontal size={19} /></button></div>{resourceRows.length ? <><div className="chart-summary"><span className="chart-big">{resourceRows.length}</span><span className="chart-label">reporting nodes</span><span className="chart-live"><i /> LIVE</span></div><div className="chart-wrap"><ResponsiveContainer width="100%" height="100%"><BarChart data={resourceRows} margin={{ top: 12, right: 8, left: -22, bottom: 0 }}><CartesianGrid stroke="#252a36" vertical={false} /><XAxis dataKey="name" tick={{ fill: '#7e8596', fontSize: 11 }} axisLine={false} tickLine={false} /><YAxis domain={[0, 100]} tick={{ fill: '#7e8596', fontSize: 10 }} tickFormatter={(v) => `${v}%`} axisLine={false} tickLine={false} /><Tooltip cursor={{ fill: '#ffffff08' }} contentStyle={{ background: '#161a24', border: '1px solid #292e3a', borderRadius: 10, color: '#f3f5f9' }} formatter={(v) => [`${v}%`, 'CPU']} /><Bar dataKey="cpu" radius={[5, 5, 0, 0]} barSize={28}>{resourceRows.map((entry) => <Cell key={entry.name} fill={entry.cpu > 80 ? '#ff9e75' : '#c6f36b'} />)}</Bar></BarChart></ResponsiveContainer></div><div className="chart-legend"><span><i className="legend-lime" />CPU utilization</span><span>Values reported by node agents</span></div></> : <div className="empty-chart"><div className="empty-chart-icon"><Activity size={21} /></div><strong>No node telemetry yet</strong><span>Live resource charts appear after a node agent checks in.</span><button onClick={() => window.dispatchEvent(new CustomEvent('nova-navigate', { detail: 'Servers' }))}>Set up a node <ArrowUpRight size={14} /></button></div>}</section>
      <section className="panel activity-panel"><div className="panel-heading"><div><h2>Recent activity</h2><p>Auditable control-plane events</p></div><button className="subtle-link">View all <ArrowUpRight size={13} /></button></div>{overview?.activity.length ? <div className="activity-list">{overview.activity.map((item) => <div className="activity-item" key={item.id}><div className="activity-mark"><Activity size={14} /></div><div className="activity-copy"><strong>{item.action}</strong><span>{item.actor} · {item.resource}</span></div><time>{formatDate(item.createdAt)}</time></div>)}</div> : <div className="empty-activity"><div className="activity-ring"><FileText size={18} /></div><strong>Nothing happening just yet</strong><span>Administrative actions will be recorded here.</span></div>}</section></div>
    <div className="bottom-grid"><section className="panel nodes-panel"><div className="panel-heading"><div><h2>Hosting nodes</h2><p>Fleet health and agent connectivity</p></div><button className="subtle-link" onClick={() => window.dispatchEvent(new CustomEvent('nova-navigate', { detail: 'Servers' }))}>All nodes <ArrowUpRight size={13} /></button></div>{overview?.nodes.length ? <div className="table-wrap"><table><thead><tr><th>NODE</th><th>REGION</th><th>STATUS</th><th>CPU</th><th>VERSION</th></tr></thead><tbody>{overview.nodes.slice(0, 4).map((node) => <tr key={node.id}><td><div className="node-name"><div className="node-icon"><Server size={15} /></div><div><strong>{node.name}</strong><span>{node.hostname}</span></div></div></td><td>{node.region ?? '—'}</td><td><span className={`status-pill ${node.online ? 'online' : 'offline'}`}><i />{node.online ? 'Online' : 'Offline'}</span></td><td>{node.cpuPercent == null ? '—' : `${Math.round(node.cpuPercent)}%`}</td><td><span className="version-tag">{node.agentVersion ?? '—'}</span></td></tr>)}</tbody></table></div> : <div className="empty-node-row"><div className="node-empty-icon"><Server size={18} /></div><span>No hosting nodes registered.</span><button onClick={() => window.dispatchEvent(new CustomEvent('nova-navigate', { detail: 'Servers' }))}>Connect a node <ChevronRight size={14} /></button></div>}</section>
      <section className="panel quick-panel"><div className="panel-heading"><div><h2>Quick access</h2><p>Common infrastructure tasks</p></div></div><div className="quick-grid">{[{ icon: Globe2, label: 'Websites', desc: 'Your hosted sites', color: 'lime', target: 'Websites' }, { icon: Server, label: 'Nodes', desc: 'Server fleet', color: 'blue', target: 'Servers' }, { icon: ShieldCheck, label: 'Security', desc: 'Policies & alerts', color: 'violet', target: 'Security' }, { icon: Settings2, label: 'Settings', desc: 'Control plane', color: 'amber', target: 'Settings' }].map(({ icon: Icon, label, desc, color, target }) => <button key={label} className="quick-tile" onClick={() => window.dispatchEvent(new CustomEvent('nova-navigate', { detail: target }))}><div className={`quick-icon ${color}`}><Icon size={17} /></div><span><strong>{label}</strong><small>{desc}</small></span><ChevronRight size={14} /></button>)}</div></section></div>
    <div className="assistant-strip"><div className="assistant-spark"><Sparkles size={17} /></div><div><strong>Nova assist</strong><span>Infrastructure guidance, with permissions that stay yours.</span></div><span className="coming-soon">OPTIONAL · NOT CONFIGURED</span><button className="assistant-button" title="Assistant not configured" disabled>Ask a question <ArrowUpRight size={14} /></button></div>
  </>;
}

function ActivityPage() {
  const [events, setEvents] = useState<ActivityItem[]>([]); const [loading, setLoading] = useState(true); const [error, setError] = useState(''); const [filter, setFilter] = useState('ALL');
  const load = async () => { setLoading(true); try { const result = await api<{ events: ActivityItem[] }>('/api/activity?limit=100'); setEvents(result.events); setError(''); } catch (e) { setError(e instanceof Error ? e.message : 'Activity records could not be loaded.'); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, []);
  const actions = Array.from(new Set(events.map((event) => event.action))).sort();
  const visible = filter === 'ALL' ? events : events.filter((event) => event.action === filter);
  return <><div className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-line" /> AUDIT TRAIL</div><h1>Activity log</h1><p className="welcome-sub">Recent administrative and provisioning events, without sensitive payloads.</p></div><button className="primary-button" disabled={loading} onClick={() => void load()}><RefreshCw size={14} />Refresh</button></div>
    {error && <div className="error-banner"><ShieldCheck size={15} /><span>{error}</span><button onClick={() => setError('')}><X size={14} /></button></div>}
    <section className="panel audit-panel"><div className="panel-heading"><div><h2>Latest events</h2><p>Showing up to 100 newest entries. Audit data is read-only here.</p></div><label className="jobs-filter">ACTION<select value={filter} onChange={(event) => setFilter(event.target.value)}><option value="ALL">All actions</option>{actions.map((action) => <option key={action} value={action}>{action}</option>)}</select></label></div>{loading ? <div className="jobs-empty">Loading activity…</div> : visible.length ? <div className="audit-list">{visible.map((event) => <article className="audit-row" key={event.id}><div className="activity-mark"><Activity size={14} /></div><div className="audit-copy"><strong>{event.action}</strong><span>{event.actor} · {event.resource}{event.resourceId ? ` · ${event.resourceId}` : ''}</span></div><time>{formatDate(event.createdAt)}</time></article>)}</div> : <div className="jobs-empty"><div className="activity-ring"><FileText size={18} /></div><strong>{filter === 'ALL' ? 'No audit events yet' : 'No matching events'}</strong><span>Security-relevant account, node and website operations are recorded here.</span></div>}<div className="jobs-footnote"><ShieldCheck size={14} /><span>Client IP addresses and event metadata are intentionally omitted from this view.</span></div></section>
  </>;
}

function AccountSettingsPage({ onUserChange }: { onUserChange: (user: User) => void }) {
  const [currentPassword, setCurrentPassword] = useState(''); const [newPassword, setNewPassword] = useState(''); const [confirmation, setConfirmation] = useState(''); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async (event: React.FormEvent) => {
    event.preventDefault(); setError(''); setNotice('');
    if (newPassword !== confirmation) { setError('The new passwords do not match.'); return; }
    setBusy(true);
    try { const result = await api<{ user: User }>('/api/auth/password', { method: 'POST', body: JSON.stringify({ currentPassword, newPassword }) }); onUserChange(result.user); setCurrentPassword(''); setNewPassword(''); setConfirmation(''); setNotice('Password updated. Other signed-in sessions have been invalidated.'); }
    catch (e) { setError(e instanceof Error ? e.message : 'Password could not be changed.'); }
    finally { setBusy(false); }
  };
  return <><div className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-line" /> ACCOUNT</div><h1>Security settings</h1><p className="welcome-sub">Update your password and invalidate other active sessions.</p></div></div><section className="panel account-security-panel"><div className="panel-heading"><div><h2>Change password</h2><p>Use a long, unique password of at least 12 characters.</p></div><div className="metric-icon lime"><ShieldCheck size={16} /></div></div>{notice && <div className="notice-banner"><ShieldCheck size={14} />{notice}</div>}{error && <div className="file-error">{error}<button onClick={() => setError('')}><X size={13} /></button></div>}<form className="account-password-form" onSubmit={(event) => void submit(event)}><label>Current password<input type="password" autoComplete="current-password" minLength={1} maxLength={128} required value={currentPassword} onChange={(event) => setCurrentPassword(event.target.value)} /></label><label>New password<input type="password" autoComplete="new-password" minLength={12} maxLength={128} required value={newPassword} onChange={(event) => setNewPassword(event.target.value)} /></label><label>Confirm new password<input type="password" autoComplete="new-password" minLength={12} maxLength={128} required value={confirmation} onChange={(event) => setConfirmation(event.target.value)} /></label><div className="inline-form-actions"><span>Changing your password signs out any older session tokens.</span><button className="primary-button" disabled={busy}>{busy ? 'Updating…' : 'Update password'}</button></div></form></section></>;
}

function PasswordChangeScreen({ user, onSuccess, onLogout }: { user: User; onSuccess: (user: User) => void; onLogout: () => Promise<void> }) {
  const [password, setPassword] = useState(''); const [confirmation, setConfirmation] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async (event: React.FormEvent) => {
    event.preventDefault(); setError('');
    if (password !== confirmation) { setError('The passwords do not match.'); return; }
    setBusy(true);
    try { const result = await api<{ user: User }>('/api/auth/password', { method: 'POST', body: JSON.stringify({ newPassword: password }) }); onSuccess(result.user); }
    catch (e) { setError(e instanceof Error ? e.message : 'Password could not be updated.'); }
    finally { setBusy(false); }
  };
  return <main className="password-gate"><div className="password-card"><div className="brand-mark"><LockKeyhole size={20} /></div><div className="eyebrow"><span className="eyebrow-line" /> ACCOUNT SECURITY</div><h1>Choose a new password</h1><p>Your account was created by an administrator. Set a private password before continuing.</p><form onSubmit={(event) => void submit(event)}><label>New password<input type="password" autoComplete="new-password" minLength={12} maxLength={128} required value={password} onChange={(event) => setPassword(event.target.value)} /></label><label>Confirm new password<input type="password" autoComplete="new-password" minLength={12} maxLength={128} required value={confirmation} onChange={(event) => setConfirmation(event.target.value)} /></label>{error && <div className="inline-form-error">{error}</div>}<button className="primary-button" disabled={busy}>{busy ? 'Updating password…' : 'Update password'}<ShieldCheck size={15} /></button></form><span className="password-user">Signed in as {user.email}</span><button className="cancel-button" onClick={() => void onLogout()}>Sign out</button></div></main>;
}

function CustomersPage() {
  const [customers, setCustomers] = useState<Customer[]>([]); const [loading, setLoading] = useState(true); const [busy, setBusy] = useState(false); const [formOpen, setFormOpen] = useState(false);
  const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [websiteLimit, setWebsiteLimit] = useState('5'); const [error, setError] = useState(''); const [credential, setCredential] = useState<{ customer: Pick<Customer, 'name' | 'email'>; oneTimePassword: string } | null>(null); const [copied, setCopied] = useState(false);
  const load = async () => { setLoading(true); try { const result = await api<{ customers: Customer[] }>('/api/customers'); setCustomers(result.customers); setError(''); } catch (e) { setError(e instanceof Error ? e.message : 'Customer records could not be loaded.'); } finally { setLoading(false); } };
  useEffect(() => { void load(); }, []);
  const create = async (event: React.FormEvent) => {
    event.preventDefault(); setBusy(true); setError(''); setCopied(false);
    try { const result = await api<{ customer: Pick<Customer, 'name' | 'email'>; oneTimePassword: string }>('/api/customers', { method: 'POST', body: JSON.stringify({ name, email, websiteLimit: Number(websiteLimit) }) }); setCredential(result); setName(''); setEmail(''); setWebsiteLimit('5'); setFormOpen(false); await load(); }
    catch (e) { setError(e instanceof Error ? e.message : 'Customer account could not be created.'); }
    finally { setBusy(false); }
  };
  const changeStatus = async (customer: Customer) => {
    const isSuspended = Boolean(customer.disabledAt);
    const nextActive = isSuspended;
    const action = nextActive ? 'Reactivate' : 'Suspend';
    if (!window.confirm(`${action} ${customer.email}? Their existing sessions will be invalidated.`)) return;
    setBusy(true); setError('');
    try { await api(`/api/customers/${encodeURIComponent(customer.id)}/status`, { method: 'PATCH', body: JSON.stringify({ active: nextActive }) }); await load(); }
    catch (e) { setError(e instanceof Error ? e.message : `Customer account could not be ${action === 'Suspend' ? 'suspended' : 'reactivated'}.`); }
    finally { setBusy(false); }
  };
  const resetPassword = async (customer: Customer) => {
    if (!window.confirm(`Reset the password for ${customer.email}? This signs out all their existing sessions.`)) return;
    setBusy(true); setError(''); setCopied(false);
    try { const result = await api<{ customer: Pick<Customer, 'name' | 'email'>; oneTimePassword: string }>(`/api/customers/${encodeURIComponent(customer.id)}/reset-password`, { method: 'POST' }); setCredential(result); await load(); }
    catch (e) { setError(e instanceof Error ? e.message : 'Customer password could not be reset.'); }
    finally { setBusy(false); }
  };
  const copy = async () => { if (!credential) return; try { await navigator.clipboard.writeText(`Email: ${credential.customer.email}\nTemporary password: ${credential.oneTimePassword}`); setCopied(true); } catch { setError('Clipboard access is unavailable. Copy the temporary password from the panel manually.'); } };
  return <><div className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-line" /> CUSTOMER ACCOUNTS</div><h1>Customers</h1><p className="welcome-sub">Create customer logins with private, one-time credentials.</p></div><button className="primary-button" onClick={() => { setFormOpen((open) => !open); setError(''); }}><Plus size={15} />Add customer</button></div>
    {error && <div className="error-banner"><ShieldCheck size={15} /><span>{error}</span><button onClick={() => setError('')}><X size={14} /></button></div>}
    {credential && <section className="panel customer-credential"><div className="bootstrap-heading"><div className="setup-symbol"><LockKeyhole size={17} /></div><div><strong>Temporary password — shown once</strong><span>Share privately. The customer must change it before using the panel.</span></div><button className="cancel-button" onClick={() => setCredential(null)}>Dismiss</button></div><div className="credential-value"><span>{credential.customer.email}</span><code>{credential.oneTimePassword}</code><button className="primary-button" onClick={() => void copy()}>{copied ? 'Copied' : 'Copy'}<FileText size={14} /></button></div></section>}
    {formOpen && <form className="panel inline-form customer-form" onSubmit={(event) => void create(event)}><div className="inline-form-copy"><strong>New customer account</strong><span>A strong temporary password is generated server-side and never stored in plaintext.</span></div><label>Full name<input required minLength={2} maxLength={80} value={name} onChange={(event) => setName(event.target.value)} placeholder="Customer name" /></label><label>Email address<input type="email" required maxLength={254} value={email} onChange={(event) => setEmail(event.target.value)} placeholder="name@example.com" /></label><label>Website limit<input type="number" required min={1} max={1000} value={websiteLimit} onChange={(event) => setWebsiteLimit(event.target.value)} /></label><div className="inline-form-actions"><span>Role <b>Customer</b> · default quota is 5 websites</span><button type="button" className="cancel-button" onClick={() => setFormOpen(false)}>Cancel</button><button className="primary-button" disabled={busy}>{busy ? 'Creating…' : 'Create account'}</button></div></form>}
    <section className="panel customer-list-panel"><div className="panel-heading"><div><h2>Customer accounts</h2><p>Customer data and website access remain tenant-scoped.</p></div><button className="subtle-link" onClick={() => void load()}><RefreshCw size={13} /> Refresh</button></div>{loading ? <div className="jobs-empty">Loading customers…</div> : customers.length ? <div className="customer-list">{customers.map((customer) => <article key={customer.id} className="customer-row"><div className="avatar customer-avatar">{customer.name.slice(0, 1).toUpperCase()}</div><div className="job-main"><strong>{customer.name}</strong><span>{customer.email}</span></div><span className={`customer-state ${customer.disabledAt ? 'customer-suspended' : customer.mustChangePassword ? 'needs-password' : 'ready-password'}`}>{customer.disabledAt ? 'Suspended' : customer.mustChangePassword ? 'Setup required' : 'Active'}</span><span className="customer-quota">{customer.websiteCount} / {customer.websiteLimit} websites</span><time>{formatDate(customer.createdAt)}</time><button className="cancel-button customer-reset" disabled={busy} onClick={() => void resetPassword(customer)}>Reset password</button><button className="cancel-button customer-status-toggle" disabled={busy} onClick={() => void changeStatus(customer)}>{customer.disabledAt ? 'Reactivate' : 'Suspend'}</button></article>)}</div> : <div className="jobs-empty"><div className="node-empty-icon"><Users size={17} /></div><strong>No customer accounts yet</strong><span>Create the first customer account to begin assigning websites.</span></div>}</section>
  </>;
}

function JobsPage({ jobs, onRefresh }: { jobs: ProvisioningJob[]; onRefresh: () => Promise<void> }) {
  const [filter, setFilter] = useState('ALL');
  const [refreshing, setRefreshing] = useState(false);
  const visible = filter === 'ALL' ? jobs : jobs.filter((job) => job.status === filter);
  const refresh = async () => { setRefreshing(true); try { await onRefresh(); } finally { setRefreshing(false); } };
  return <>
    <div className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-line" /> OPERATIONS</div><h1>Provisioning jobs</h1><p className="welcome-sub">Track real node operations and their latest reported outcomes.</p></div><button className="primary-button" disabled={refreshing} onClick={() => void refresh()}><RefreshCw size={14} />{refreshing ? 'Refreshing' : 'Refresh'}</button></div>
    <section className="panel jobs-panel"><div className="panel-heading"><div><h2>Recent operations</h2><p>Jobs are retried automatically when a node is temporarily unavailable.</p></div><label className="jobs-filter">STATUS<select value={filter} onChange={(event) => setFilter(event.target.value)}><option value="ALL">All statuses</option><option value="QUEUED">Queued</option><option value="RUNNING">Running</option><option value="SUCCEEDED">Succeeded</option><option value="FAILED">Failed</option><option value="CANCELLED">Cancelled</option></select></label></div>
      {visible.length ? <div className="jobs-list">{visible.map((job) => <article className="job-row" key={job.id}><div className={`job-icon job-${job.status.toLowerCase()}`}><Zap size={16} /></div><div className="job-main"><strong>{job.type === 'website.create' ? 'Create website' : job.type === 'website.delete' ? 'Delete website' : job.type === 'website.ssl.enable' ? 'Enable HTTPS' : job.type.replaceAll('.', ' ')}</strong><span>{job.website?.primaryDomain ?? (job.type === 'website.delete' ? 'Website removed' : 'Website record unavailable')} · {job.id.slice(0, 12)}</span></div><span className={`status-pill ${job.status === 'SUCCEEDED' ? 'online' : job.status === 'QUEUED' || job.status === 'RUNNING' ? 'job-active' : 'offline'}`}><i />{job.status}</span><div className="job-meta"><span>{job.attempts} {job.attempts === 1 ? 'attempt' : 'attempts'}</span><time>{formatDate(job.updatedAt)}</time></div></article>)}</div> : <div className="jobs-empty"><div className="node-empty-icon"><Zap size={17} /></div><strong>{filter === 'ALL' ? 'No provisioning jobs yet' : `No ${filter.toLowerCase()} jobs`}</strong><span>Website operations appear here as soon as they are submitted to the control plane.</span></div>}
      <div className="jobs-footnote"><ShieldCheck size={14} /><span>Only operation status is shown here; internal node error details are kept out of customer responses.</span></div>
    </section>
  </>;
}

function WebsitesPage({ websites, canProvision, onRefresh }: { websites: Website[]; canProvision: boolean; onRefresh: () => Promise<void> }) {
  const [formOpen, setFormOpen] = useState(false);
  const [domain, setDomain] = useState('');
  const [busy, setBusy] = useState(false);
  const [notice, setNotice] = useState('');
  const [formError, setFormError] = useState('');
  const createWebsite = async (event: React.FormEvent) => {
    event.preventDefault(); setBusy(true); setFormError(''); setNotice('');
    try {
      await api('/api/websites', { method: 'POST', headers: { 'Idempotency-Key': crypto.randomUUID() }, body: JSON.stringify({ primaryDomain: domain, runtime: 'static' }) });
      setDomain(''); setFormOpen(false); setNotice(`Provisioning queued for ${domain.toLowerCase()}. The node agent will report its result here.`); await onRefresh();
    } catch (e) { setFormError(e instanceof Error ? e.message : 'Website request failed.'); }
    finally { setBusy(false); }
  };
  const enableTLS = async (site: Website) => {
    if (!window.confirm(`Request a Let's Encrypt certificate for ${site.primaryDomain}? Its DNS must already point to this node and public port 80 must be reachable.`)) return;
    setBusy(true); setNotice(''); setFormError('');
    try { await api(`/api/websites/${encodeURIComponent(site.id)}/ssl`, { method: 'POST', headers: { 'Idempotency-Key': crypto.randomUUID() } }); setNotice(`TLS certificate request queued for ${site.primaryDomain}. The website will redirect to HTTPS when issuance succeeds.`); await onRefresh(); }
    catch (e) { setFormError(e instanceof Error ? e.message : 'TLS request failed.'); }
    finally { setBusy(false); }
  };
  const deleteWebsite = async (site: Website) => {
    if (!window.confirm(`Queue deletion of ${site.primaryDomain}? Its files and Nginx site will be removed from the hosting node.`)) return;
    setNotice('');
    try { await api(`/api/websites/${encodeURIComponent(site.id)}`, { method: 'DELETE', headers: { 'Idempotency-Key': crypto.randomUUID() } }); setNotice(`Deletion queued for ${site.primaryDomain}.`); await onRefresh(); }
    catch (e) { setFormError(e instanceof Error ? e.message : 'Website deletion failed.'); }
  };
  return <><div className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-line" /> HOSTING</div><h1>Websites</h1><p className="welcome-sub">Static websites provisioned on your verified hosting nodes.</p></div><button className="primary-button" disabled={!canProvision} title={canProvision ? 'Create a static website' : 'Connect a healthy node before provisioning'} onClick={() => { setFormOpen((open) => !open); setFormError(''); }}><Plus size={16} />Create website</button></div>
    {notice && <div className="notice-banner"><Activity size={15} /><span>{notice}</span><button onClick={() => setNotice('')}><X size={14} /></button></div>}
    {formOpen && <form className="panel inline-form" onSubmit={createWebsite}><div className="inline-form-copy"><strong>Provision a static website</strong><span>Nova creates a confined site directory and managed Nginx virtual host on a healthy node.</span></div><label>Domain<input required pattern="(?=.{1,253}$)(?:[a-zA-Z0-9](?:[a-zA-Z0-9-]{0,61}[a-zA-Z0-9])?\.)+[a-zA-Z]{2,63}" value={domain} onChange={(event) => setDomain(event.target.value)} placeholder="www.example.com" /></label>{formError && <div className="inline-form-error">{formError}</div>}<div className="inline-form-actions"><span>Runtime <b>Static HTML</b></span><button type="button" className="cancel-button" onClick={() => setFormOpen(false)}>Cancel</button><button className="primary-button" disabled={busy}>{busy ? 'Queueing…' : 'Queue provisioning'}<ArrowUpRight size={14} /></button></div></form>}
    {formError && !formOpen && <div className="error-banner"><ShieldCheck size={15} /><span>{formError}</span><button onClick={() => setFormError('')}><X size={14} /></button></div>}
    <div className="panel website-table-panel">{websites.length ? <div className="table-wrap"><table><thead><tr><th>DOMAIN</th><th>RUNTIME</th><th>NODE</th><th>STATUS</th><th>HTTPS</th><th>CREATED</th><th /></tr></thead><tbody>{websites.map((site) => <tr key={site.id}><td><div className="domain-cell"><Globe2 size={15} /><strong>{site.primaryDomain}</strong></div></td><td><span className="runtime-tag">{site.runtime}</span></td><td>{site.node?.name ?? 'Unassigned'}</td><td><span className={`status-pill ${site.status === 'ACTIVE' ? 'online' : 'offline'}`}><i />{site.status}</span></td><td><span className={`status-pill ${site.tlsStatus === 'active' ? 'online' : site.tlsStatus === 'pending' ? 'job-active' : 'offline'}`}><i />{site.tlsStatus.toUpperCase()}</span>{site.status === 'ACTIVE' && site.tlsStatus !== 'active' && site.tlsStatus !== 'pending' && <button className="tls-enable-link" disabled={busy} onClick={() => void enableTLS(site)}>Enable</button>}</td><td>{formatDate(site.createdAt)}</td><td><button className="icon-button" aria-label={`Delete ${site.primaryDomain}`} title="Queue website deletion" disabled={(site.status !== 'ACTIVE' && site.status !== 'FAILED') || site.tlsStatus === 'pending'} onClick={() => void deleteWebsite(site)}><MoreHorizontal size={17} /></button></td></tr>)}</tbody></table></div> : <div className="website-empty"><div className="website-empty-art"><div className="orbit orbit-one" /><div className="orbit orbit-two" /><div className="globe-art"><Globe2 size={27} /></div><div className="sparkle-dot">✦</div></div><h2>No websites yet</h2><p>{canProvision ? 'Add a domain to provision a real static site and managed Nginx vhost on a healthy node.' : 'Connect a trusted Nova hosting node first. Provisioning remains locked until the node agent is authenticated and healthy.'}</p><div className="disabled-explainer"><LockKeyhole size={15} /><span>{canProvision ? 'Only static HTML is enabled in this initial provisioning slice.' : 'Provisioning is intentionally locked until a node is verified.'}</span></div></div>}</div></>;
}

type FileEntry = { name: string; type: 'file' | 'directory' | 'symlink'; size: number; modifiedAt: string };
type OpenFile = { path: string; content: string; image?: string };
const bytesToBase64 = (bytes: Uint8Array) => { let binary = ''; for (let offset = 0; offset < bytes.length; offset += 32_768) binary += String.fromCharCode(...bytes.subarray(offset, offset + 32_768)); return btoa(binary); };
const base64ToBytes = (value: string) => Uint8Array.from(atob(value), (character) => character.charCodeAt(0));
const editorLanguage = (name: string) => ({ html: 'html', htm: 'html', css: 'css', js: 'javascript', mjs: 'javascript', cjs: 'javascript', ts: 'typescript', json: 'json', php: 'php', py: 'python', sql: 'sql', yaml: 'yaml', yml: 'yaml', md: 'markdown', xml: 'xml', sh: 'shell' }[name.split('.').pop()?.toLowerCase() ?? ''] ?? 'plaintext');

function FilesPage({ websites }: { websites: Website[] }) {
  const [siteId, setSiteId] = useState(''); const [folder, setFolder] = useState(''); const [entries, setEntries] = useState<FileEntry[]>([]); const [filter, setFilter] = useState('');
  const [loading, setLoading] = useState(false); const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [notice, setNotice] = useState(''); const [openFile, setOpenFile] = useState<OpenFile | null>(null);
  const activeSites = websites.filter((site) => site.status === 'ACTIVE');
  const selected = websites.find((site) => site.id === siteId);
  useEffect(() => { if (!siteId && activeSites.length) setSiteId(activeSites[0]?.id ?? ''); }, [siteId, activeSites]);
  useEffect(() => {
    if (!siteId || !selected || selected.status !== 'ACTIVE') { setEntries([]); return; }
    let ignore = false; setLoading(true); setError('');
    const query = new URLSearchParams({ action: 'list', path: folder });
    api<{ entries: FileEntry[] }>(`/api/websites/${encodeURIComponent(siteId)}/files?${query}`).then((result) => { if (!ignore) setEntries(result.entries); }).catch((e) => { if (!ignore) setError(e instanceof Error ? e.message : 'Directory listing failed.'); }).finally(() => { if (!ignore) setLoading(false); });
    return () => { ignore = true; };
  }, [siteId, folder, selected]);
  const filePath = (name: string) => folder ? `${folder}/${name}` : name;
  const listAgain = async () => { const query = new URLSearchParams({ action: 'list', path: folder }); const result = await api<{ entries: FileEntry[] }>(`/api/websites/${encodeURIComponent(siteId)}/files?${query}`); setEntries(result.entries); };
  const read = async (path: string) => api<{ contentBase64: string; size: number }>(`/api/websites/${encodeURIComponent(siteId)}/files?${new URLSearchParams({ action: 'read', path })}`);
  const open = async (entry: FileEntry) => {
    const path = filePath(entry.name); if (entry.type === 'directory') { setFolder(path); setFilter(''); return; }
    setBusy(true); setError('');
    try { const data = await read(path); const bytes = base64ToBytes(data.contentBase64); const extension = entry.name.split('.').pop()?.toLowerCase();
      if (['png', 'jpg', 'jpeg', 'gif', 'webp', 'svg'].includes(extension ?? '')) { const mime = extension === 'svg' ? 'image/svg+xml' : `image/${extension === 'jpg' ? 'jpeg' : extension}`; setOpenFile({ path, content: '', image: `data:${mime};base64,${data.contentBase64}` }); }
      else setOpenFile({ path, content: new TextDecoder().decode(bytes) });
    } catch (e) { setError(e instanceof Error ? e.message : 'File could not be opened.'); } finally { setBusy(false); }
  };
  const mutate = async (body: Record<string, string>, success: string) => {
    setBusy(true); setError(''); setNotice('');
    try { await api(`/api/websites/${encodeURIComponent(siteId)}/files`, { method: 'POST', body: JSON.stringify(body) }); setNotice(success); await listAgain(); }
    catch (e) { setError(e instanceof Error ? e.message : 'File operation failed.'); }
    finally { setBusy(false); }
  };
  const createFile = async () => {
    const name = window.prompt('New file name, for example index.html'); if (!name) return;
    const path = filePath(name); await mutate({ operation: 'files.write', path, contentBase64: '' }, `Created ${name}`); setOpenFile({ path, content: '' });
  };
  const createFolder = async () => { const name = window.prompt('New folder name'); if (!name) return; await mutate({ operation: 'files.mkdir', path: filePath(name) }, `Created folder ${name}`); };
  const rename = async (entry: FileEntry) => { const name = window.prompt('Rename to', entry.name); if (!name || name === entry.name) return; await mutate({ operation: 'files.rename', path: filePath(entry.name), newPath: filePath(name) }, `Renamed to ${name}`); };
  const remove = async (entry: FileEntry) => { if (!window.confirm(`Permanently delete ${entry.name}?`)) return; await mutate({ operation: 'files.delete', path: filePath(entry.name) }, `Deleted ${entry.name}`); };
  const upload = async (event: React.ChangeEvent<HTMLInputElement>) => {
    const files = Array.from(event.target.files ?? []); event.target.value = '';
    for (const file of files) {
      if (file.size > 8 * 1024 * 1024) { setError(`${file.name} is over the 8 MiB per-file limit.`); continue; }
      setBusy(true); setError('');
      try { const bytes = new Uint8Array(await file.arrayBuffer()); await api(`/api/websites/${encodeURIComponent(siteId)}/files`, { method: 'POST', body: JSON.stringify({ operation: 'files.write', path: filePath(file.name), contentBase64: bytesToBase64(bytes) }) }); setNotice(`Uploaded ${file.name}`); await listAgain(); }
      catch (e) { setError(e instanceof Error ? e.message : `Upload failed for ${file.name}.`); }
      finally { setBusy(false); }
    }
  };
  const save = async () => { if (!openFile || openFile.image) return; const encoded = bytesToBase64(new TextEncoder().encode(openFile.content)); await mutate({ operation: 'files.write', path: openFile.path, contentBase64: encoded }, `Saved ${openFile.path}`); };
  const download = async (entry: FileEntry) => {
    try { const data = await read(filePath(entry.name)); const blob = new Blob([base64ToBytes(data.contentBase64)]); const url = URL.createObjectURL(blob); const link = document.createElement('a'); link.href = url; link.download = entry.name; link.click(); URL.revokeObjectURL(url); }
    catch (e) { setError(e instanceof Error ? e.message : 'Download failed.'); }
  };
  const parts = folder ? folder.split('/') : [];
  const visible = entries.filter((entry) => entry.name.toLowerCase().includes(filter.toLowerCase())).sort((a, b) => Number(b.type === 'directory') - Number(a.type === 'directory') || a.name.localeCompare(b.name));
  return <><div className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-line" /> WEBSITE TOOLS</div><h1>File manager</h1><p className="welcome-sub">Browse and edit files confined to a website’s document root.</p></div><div className="file-site-select"><label>WEBSITE<select value={siteId} onChange={(e) => { setSiteId(e.target.value); setFolder(''); setOpenFile(null); }}><option value="">Choose an active website</option>{activeSites.map((site) => <option key={site.id} value={site.id}>{site.primaryDomain}</option>)}</select></label></div></div>
    {!activeSites.length ? <div className="panel website-empty"><div className="website-empty-art"><div className="orbit orbit-one" /><div className="orbit orbit-two" /><div className="globe-art"><HardDrive size={25} /></div></div><h2>No active website files</h2><p>File access is scoped to active websites and enabled only through a signed node-agent request.</p></div> : <div className="panel file-manager-panel">
      <div className="file-toolbar"><div className="file-breadcrumb"><button onClick={() => setFolder('')} title="Document root"><HardDrive size={14} /></button><span>/</span>{parts.map((part, index) => <span className="crumb-part" key={`${part}-${index}`}><button onClick={() => setFolder(parts.slice(0, index + 1).join('/'))}>{part}</button><span>/</span></span>)}</div><button className="file-icon-button" disabled={busy || !folder} onClick={() => setFolder(parts.slice(0, -1).join('/'))} title="Up one directory"><ChevronLeft size={15} /></button><div className="file-search"><Search size={14} /><input value={filter} onChange={(e) => setFilter(e.target.value)} placeholder="Filter current folder" /></div><button className="file-icon-button" disabled={loading || busy} onClick={() => void listAgain()} title="Refresh"><RefreshCw size={14} /></button><button className="file-action-button" disabled={busy || !siteId} onClick={() => void createFolder()}><FolderPlus size={14} />New folder</button><button className="file-action-button" disabled={busy || !siteId} onClick={() => void createFile()}><Plus size={14} />New file</button><label className="file-action-button upload-label"><Upload size={14} />Upload<input type="file" multiple onChange={(event) => void upload(event)} /></label></div>
      {notice && <div className="notice-banner"><Activity size={14} /><span>{notice}</span><button onClick={() => setNotice('')}><X size={13} /></button></div>}{error && <div className="file-error"><ShieldCheck size={14} />{error}<button onClick={() => setError('')}><X size={13} /></button></div>}
      <div className="file-list-head"><span>NAME</span><span>TYPE</span><span>SIZE</span><span>MODIFIED</span><span>ACTIONS</span></div>
      {loading ? <div className="file-empty-state">Loading directory…</div> : !visible.length ? <div className="file-empty-state"><div className="node-empty-icon"><FolderPlus size={17} /></div><strong>This folder is empty</strong><span>Upload or create a file to get started.</span></div> : <div className="file-rows">{visible.map((entry) => <div className="file-row" key={entry.name}><button className="file-entry-name" onClick={() => void open(entry)}>{entry.type === 'directory' ? <FolderPlus size={16} /> : entry.type === 'symlink' ? <FileText size={15} /> : <Code2 size={15} />}<span>{entry.name}</span></button><span className="file-type">{entry.type}</span><span className="file-size">{entry.type === 'directory' ? '—' : entry.size < 1024 ? `${entry.size} B` : `${(entry.size / 1024).toFixed(1)} KB`}</span><span className="file-date">{formatDate(entry.modifiedAt)}</span><div className="file-actions"><button title="Rename" onClick={() => void rename(entry)}><Pencil size={13} /></button>{entry.type === 'file' && <button title="Download (2 MiB read limit)" onClick={() => void download(entry)}><Download size={14} /></button>}<button title="Delete" onClick={() => void remove(entry)}><Trash2 size={13} /></button></div></div>)}</div>}
    </div>}
    {openFile && <div className="editor-backdrop" role="presentation" onClick={(e) => { if (e.target === e.currentTarget) setOpenFile(null); }}><section className="editor-dialog" role="dialog" aria-modal="true" aria-label={`Edit ${openFile.path}`}><header><div><Code2 size={16} /><strong>{openFile.path}</strong>{openFile.image && <span>IMAGE PREVIEW</span>}</div><div><button className="editor-save" disabled={busy || Boolean(openFile.image)} onClick={() => void save()}><FileText size={14} />Save</button><button className="icon-button" onClick={() => setOpenFile(null)} aria-label="Close editor"><X size={17} /></button></div></header>{openFile.image ? <div className="image-preview"><img src={openFile.image} alt={openFile.path} /></div> : <Editor height="min(68vh, 700px)" language={editorLanguage(openFile.path)} theme="vs-dark" value={openFile.content} onChange={(value) => setOpenFile((current) => current ? { ...current, content: value ?? '' } : current)} options={{ minimap: { enabled: false }, fontSize: 13, lineNumbers: 'on', wordWrap: 'on', automaticLayout: true, scrollBeyondLastLine: false, tabSize: 2, padding: { top: 14 } }} />}</section></div>}
  </>;
}

function ServersPage({ overview, onRefresh }: { overview: Overview | null; onRefresh: () => Promise<void> }) {
  const [formOpen, setFormOpen] = useState(false);
  const [bootstrap, setBootstrap] = useState<{ nodeId: string; sharedSecret: string } | null>(null);
  const [name, setName] = useState(''); const [hostname, setHostname] = useState(''); const [region, setRegion] = useState(''); const [agentUrl, setAgentUrl] = useState('');
  const [formError, setFormError] = useState(''); const [busy, setBusy] = useState(false); const [copied, setCopied] = useState(false);
  const registerNode = async (event: React.FormEvent) => {
    event.preventDefault(); setBusy(true); setFormError(''); setBootstrap(null);
    try {
      const result = await api<{ bootstrap: { nodeId: string; sharedSecret: string } }>('/api/nodes', { method: 'POST', body: JSON.stringify({ name, hostname, region: region || undefined, agentUrl }) });
      setBootstrap(result.bootstrap); setFormOpen(false); setName(''); setHostname(''); setRegion(''); setAgentUrl(''); await onRefresh();
    } catch (e) { setFormError(e instanceof Error ? e.message : 'Node registration failed.'); }
    finally { setBusy(false); }
  };
  const copyBootstrap = async () => {
    if (!bootstrap) return;
    const text = `NOVA_NODE_ID=${bootstrap.nodeId}\nNOVA_SHARED_SECRET=${bootstrap.sharedSecret}\nNOVA_CONTROL_URL=https://your-control-plane.example\nNOVA_ACME_EMAIL=ops@example.com\nNOVA_ACME_STAGING=false`;
    try { await navigator.clipboard.writeText(text); setCopied(true); window.setTimeout(() => setCopied(false), 1800); } catch { setFormError('Clipboard access is unavailable; copy the displayed secret manually.'); }
  };
  return <><div className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-line" /> INFRASTRUCTURE</div><h1>Hosting nodes</h1><p className="welcome-sub">Manage the trusted Linux servers that power your hosting fleet.</p></div><button className="primary-button" onClick={() => { setFormOpen((open) => !open); setFormError(''); }}><Plus size={16} />Register node</button></div>
    {formError && <div className="error-banner"><ShieldCheck size={15} /><span>{formError}</span><button onClick={() => setFormError('')}><X size={14} /></button></div>}
    {bootstrap && <div className="panel bootstrap-panel"><div className="bootstrap-heading"><div className="setup-symbol"><LockKeyhole size={18} /></div><div><strong>Node credentials issued once</strong><span>Copy this secret into the node’s root-owned environment file now. It cannot be retrieved again.</span></div><button className="cancel-button" onClick={() => setBootstrap(null)}>Dismiss</button></div><div className="secret-row"><code>NOVA_NODE_ID={bootstrap.nodeId}</code><code>NOVA_SHARED_SECRET={bootstrap.sharedSecret}</code><button className="primary-button" onClick={() => void copyBootstrap()}>{copied ? 'Copied' : 'Copy bootstrap'}<FileText size={14} /></button></div><p>Install Nginx and Certbot at <code>/usr/bin/certbot</code>, configure a trusted agent TLS certificate and ACME email, and set <code>NOVA_CONTROL_URL</code> to this panel’s HTTPS origin. Open inbound port 80 for website HTTP-01 challenges. Do not paste the shared secret into tickets or shell history.</p></div>}
    {formOpen && <form className="panel inline-form node-enroll-form" onSubmit={registerNode}><div className="inline-form-copy"><strong>Register a Linux host</strong><span>Enrollment creates a per-node HMAC credential encrypted at rest. The agent must use a trusted HTTPS certificate.</span></div><label>Node name<input required minLength={2} maxLength={80} value={name} onChange={(e) => setName(e.target.value)} placeholder="Compute · Mumbai 01" /></label><label>Hostname<input required maxLength={253} value={hostname} onChange={(e) => setHostname(e.target.value)} placeholder="host01.example.net" /></label><label>Region<input maxLength={80} value={region} onChange={(e) => setRegion(e.target.value)} placeholder="ap-south-1" /></label><label>Agent HTTPS URL<input required type="url" value={agentUrl} onChange={(e) => setAgentUrl(e.target.value)} placeholder="https://host01.example.net:8443" /></label><div className="inline-form-actions"><span>Enrollment uses signed heartbeats and an allowlisted agent protocol.</span><button type="button" className="cancel-button" onClick={() => setFormOpen(false)}>Cancel</button><button className="primary-button" disabled={busy}>{busy ? 'Registering…' : 'Register and issue secret'}<ArrowUpRight size={14} /></button></div></form>}
    <div className="server-summary-grid"><div className="panel server-summary"><div className="summary-icon lime"><Server size={18} /></div><span>REGISTERED NODES</span><strong>{overview?.metrics.nodes ?? '—'}</strong></div><div className="panel server-summary"><div className="summary-icon blue"><Activity size={18} /></div><span>HEALTHY AGENTS</span><strong>{overview?.metrics.liveNodes ?? '—'}</strong></div><div className="panel server-summary"><div className="summary-icon violet"><Box size={18} /></div><span>WEBSITES</span><strong>{overview?.metrics.websites ?? '—'}</strong></div></div><div className="panel server-list-panel"><div className="panel-heading"><div><h2>Node fleet</h2><p>Signed heartbeat freshness threshold: 90 seconds</p></div><span className="live-tag"><i />LIVE STATUS</span></div>{overview?.nodes.length ? <div className="node-cards">{overview.nodes.map((node) => <div className="node-card" key={node.id}><div className="node-card-top"><div className="node-icon large"><Server size={18} /></div><span className={`status-pill ${node.online ? 'online' : 'offline'}`}><i />{node.online ? 'Online' : 'Offline'}</span></div><h3>{node.name}</h3><p>{node.hostname}</p><div className="node-card-meta"><span>{node.region ?? 'No region'}</span><span>Agent {node.agentVersion ?? 'unknown'}</span></div><div className="node-resources"><div><span>CPU</span><strong>{node.cpuPercent == null ? '—' : `${Math.round(node.cpuPercent)}%`}</strong></div><div><span>Memory</span><strong>{node.memoryUsed && node.memoryTotal ? `${shortBytes(node.memoryUsed)} / ${shortBytes(node.memoryTotal)}` : '—'}</strong></div><div><span>Disk</span><strong>{node.diskUsed && node.diskTotal ? `${shortBytes(node.diskUsed)} / ${shortBytes(node.diskTotal)}` : '—'}</strong></div></div></div>)}</div> : <div className="empty-servers"><div className="server-empty-orb"><Server size={25} /></div><h2>No nodes connected</h2><p>Register a node, build the Go agent, and install it with a valid TLS certificate. It becomes healthy only after a signed heartbeat is verified.</p><a href="https://github.com/anuragbiswas9733832815-boop/NovaPanel" target="_blank" rel="noreferrer">Read project documentation <ArrowUpRight size={14} /></a></div>}</div></>;
}

function UnavailablePage({ title, icon: Icon }: { title: string; icon: typeof Globe2 }) {
  return <><div className="welcome-row"><div><div className="eyebrow"><span className="eyebrow-line" /> NOVA PLATFORM</div><h1>{title}</h1><p className="welcome-sub">A clear view of your hosting operations.</p></div></div><section className="panel feature-placeholder"><div className="feature-placeholder-icon"><Icon size={22} /></div><span className="feature-kicker">FOUNDATION IN PROGRESS</span><h2>{title} service is not connected</h2><p>This control-plane foundation does not simulate production operations. Connect and verify the required infrastructure integration before enabling this module.</p><div className="feature-status"><span><i />API surface</span><b>Not enabled</b></div><div className="feature-status"><span><i />Production operations</span><b>Locked</b></div></section></>;
}

function AuthScreen({ setupEnabled, health, onSuccess }: { setupEnabled: boolean; health: Health | null; onSuccess: (user: User) => void }) {
  const [setup, setSetup] = useState(setupEnabled);
  const [identifier, setIdentifier] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  const submit = async (event: React.FormEvent) => { event.preventDefault(); setError(''); setBusy(true); try { const result = await api<{ user: User }>(setup ? '/api/install/initialize' : '/api/auth/login', { method: 'POST', body: JSON.stringify(setup ? {} : { identifier, password }) }); onSuccess(result.user); } catch (e) { setError(e instanceof Error ? e.message : 'Request failed'); } finally { setBusy(false); } };
  return <div className="auth-layout"><div className="auth-decoration"><div className="auth-glow" /><div className="auth-top-brand"><div className="brand-mark"><Sparkles size={19} /></div><span>nova<span className="brand-light">hosting</span></span></div><div className="auth-message"><span className="eyebrow"><span className="eyebrow-line" /> CONTROL YOUR CLOUD</span><h1>Infrastructure,<br /><em>without the noise.</em></h1><p>A clear, independent control plane for the hosting you build and run.</p><div className="auth-visual"><div className="visual-grid" /><div className="visual-line line-a" /><div className="visual-line line-b" /><div className="visual-node node-a"><Server size={16} /></div><div className="visual-node node-b"><Globe2 size={16} /></div><div className="visual-node node-c"><ShieldCheck size={16} /></div><div className="visual-center"><Sparkles size={23} /></div><div className="visual-caption">YOUR INFRASTRUCTURE · YOUR RULES</div></div></div><div className="auth-decoration-footer"><span>Built for operators, by operators.</span><span>Independent by design <ArrowUpRight size={13} /></span></div></div><main className="auth-main"><div className="auth-mobile-brand"><div className="brand-mark"><Sparkles size={19} /></div><span>nova<span className="brand-light">hosting</span></span></div><div className="auth-box"><div className="auth-kicker"><span className={`footer-dot ${health?.status === 'ok' ? 'good' : 'warn'}`} />{health?.status === 'ok' ? 'CONTROL PLANE ONLINE' : 'CHECKING CONTROL PLANE'}</div><h2>{setup ? 'Initialize Nova Hosting' : 'Welcome back'}</h2><p className="auth-subtitle">{setup ? 'The first-run wizard creates the one-time Super Administrator and Local Node record. The agent must then be installed and verified on this Linux host.' : 'Sign in to your Nova Hosting control plane.'}</p>{setup && <div className="auth-system-note"><LockKeyhole size={15} /><span>Initial login: username <b>admin</b>, password <b>admin</b>. You will be required to choose a new password immediately. This weak bootstrap is created once and is never restored on upgrades.</span></div>}<form onSubmit={submit}>{!setup && <><label>Username or email<input required autoComplete="username" value={identifier} onChange={(e) => setIdentifier(e.target.value)} placeholder="admin or you@company.com" /></label><label>Password<input required maxLength={128} type="password" autoComplete="current-password" value={password} onChange={(e) => setPassword(e.target.value)} placeholder="Enter your password" /></label></>}{error && <div className="auth-error"><ShieldCheck size={15} />{error}</div>}<button className="auth-submit" disabled={busy || !health || health.database !== 'connected' || health.schema !== 'ready'}>{busy ? 'Please wait…' : setup ? 'Initialize installation' : 'Sign in'}<ChevronRight size={16} /></button></form>{(!health || health.database !== 'connected' || health.schema !== 'ready') && <div className="auth-system-note"><LockKeyhole size={15} /><span>{health?.database !== 'connected' ? 'PostgreSQL is unavailable. Start the database and retry.' : 'Database schema is missing. Start the API after configuring DATABASE_URL; startup applies pending Prisma migrations.'}</span></div>}{!setup && <div className="auth-help">Secure access · Sessions expire after 8 hours</div>}</div><div className="auth-bottom"><span>Nova Hosting <b>·</b> Control plane</span><button><CircleHelp size={14} /> Help</button></div></main></div>;
}
